package com.digitaloffice.document;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="documents",indexes=@Index(name="ix_documents_project_status",columnList="project_id,status"))
public class Document {
 @Id private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(nullable=false) private String title; private String description; @Column(nullable=false) private int currentVersion; @Enumerated(EnumType.STRING) @Column(nullable=false) private DocumentStatus status; @Column(nullable=false) private UUID createdBy; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt;
 protected Document(){} public Document(UUID p,String t,String d,UUID a){id=UUID.randomUUID();projectId=p;title=t;description=d;createdBy=a;currentVersion=0;status=DocumentStatus.ACTIVE;createdAt=Instant.now();updatedAt=createdAt;}
 public UUID getId(){return id;} public UUID getProjectId(){return projectId;} public UUID getCreatedBy(){return createdBy;} public String getTitle(){return title;} public String getDescription(){return description;} public int getCurrentVersion(){return currentVersion;} public DocumentStatus getStatus(){return status;} public void update(String t,String d){if(status==DocumentStatus.ARCHIVED)throw new IllegalStateException("Archived document cannot be edited");title=t;description=d;updatedAt=Instant.now();} public void archive(){if(status==DocumentStatus.ARCHIVED)throw new IllegalStateException("Document is already archived");status=DocumentStatus.ARCHIVED;updatedAt=Instant.now();} public void nextVersion(){if(status==DocumentStatus.ARCHIVED)throw new IllegalStateException("Archived document cannot receive versions");currentVersion++;updatedAt=Instant.now();}
}
